            new int[] {1, 6, 6, 1, 23},
            new int[] {2, 0, 0, 0, 8, 9, 10},
        };

        for (int i = 0; i < Q; i++)
        {
            int type = queries[i][0];
            int x, y, z, val, X, Y, Z;
